// vc20 UI icon pack + applier (gloss navy/gold set)
window.UICONS={hint:"data:image/png;base64,",magnifier:"data:image/png;base64,",zoomin:"data:image/png;base64,",zoomout:"data:image/png;base64,",reset:"data:image/png;base64,",settings:"data:image/png;base64,",exit:"data:image/png;base64,",check:"data:image/png;base64,",lock:"data:image/png;base64,"};
(function(){
  if(!window.UICONS) return;
  var css = document.createElement('style');
  css.textContent = "img.uicon{height:1.2em;width:1.2em;vertical-align:-0.22em;border-radius:4px;pointer-events:none}" +
    ".view-btn img.uicon{height:26px;width:26px;vertical-align:middle}" +
    ".icon-btn img.uicon{height:26px;width:26px;vertical-align:middle}" +
    ".chip.locked img.uicon{height:30px;width:30px}" +
    ".target .check img.uicon{height:16px;width:16px;vertical-align:-3px}" +
    ".hint-btn img.uicon{height:20px;width:20px;vertical-align:-4px}" +
    ".bottom-heading img.uicon,.brand img.uicon{height:22px;width:22px;vertical-align:-4px}";
  document.head.appendChild(css);
  function img(k){ return '<img class="uicon" src="'+UICONS[k]+'" alt="">'; }
  function swapEmoji(el, emoji, key){
    if(!el || el.dataset.uiconDone) return;
    if(el.innerHTML.indexOf(emoji) !== -1){
      el.innerHTML = el.innerHTML.split(emoji).join(img(key));
      el.dataset.uiconDone = "1";
    }
  }
  function apply(root){
    root = root || document;
    // static buttons
    var m = [['exitButton','exit'],['settingsButton','settings'],['zoomIn','zoomin'],['zoomOut','zoomout'],['resetView','reset']];
    m.forEach(function(p){
      var el = document.getElementById(p[0]);
      if(el && !el.dataset.uiconDone){ el.innerHTML = img(p[1]); el.dataset.uiconDone = "1"; }
    });
    // hint button: replace bulb glyph, keep label + count
    var hb = document.getElementById('hintButton');
    if(hb) swapEmoji(hb, '\u{1F4A1}', 'hint');
    // headers with magnifier
    Array.prototype.forEach.call(document.querySelectorAll('.bottom-heading strong, header strong'), function(el){
      swapEmoji(el, '\u{1F50D}', 'magnifier');
    });
    // dynamic: locked level chips
    Array.prototype.forEach.call(document.querySelectorAll('.chip.locked'), function(el){
      if(!el.dataset.uiconDone && (el.textContent.indexOf('\u{1F512}') !== -1)){
        el.innerHTML = img('lock'); el.dataset.uiconDone = "1";
      }
    });
    // dynamic: found check marks in tray
    Array.prototype.forEach.call(document.querySelectorAll('.target .check'), function(el){
      if(!el.dataset.uiconDone){ el.innerHTML = img('check'); el.dataset.uiconDone = "1"; }
    });
  }
  window.applyUIIcons = apply;
  var obs = new MutationObserver(function(muts){
    var hit = false;
    for(var i=0;i<muts.length;i++){ if(muts[i].addedNodes.length){ hit = true; break; } }
    if(hit) apply(document);
  });
  function boot(){ apply(document); obs.observe(document.body, {childList:true, subtree:true}); }
  if(document.body) boot(); else document.addEventListener('DOMContentLoaded', boot);
})();
